package com.quincaisoft.purchasing.application;import com.quincaisoft.purchasing.api.*;import com.quincaisoft.purchasing.infrastructure.*;import com.quincaisoft.suppliers.api.SupplierService;import com.quincaisoft.shared.*;import jakarta.persistence.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class DefaultPayablesService implements PayablesService{
 private final EntityManager em;private final ScopedTransactions tx;private final SupplierService suppliers;public DefaultPayablesService(EntityManager em,ScopedTransactions tx,SupplierService suppliers){this.em=em;this.tx=tx;this.suppliers=suppliers;}
 public List<Balance> balances(){return tx.execute(()->em.createQuery("select r from PayableBalance r order by r.id",PayableBalance.class).setMaxResults(500).getResultList().stream().map(r->new Balance(r.id,r.supplierId,""+r.originalXaf,""+r.paidXaf,""+Math.subtractExact(r.originalXaf,r.paidXaf),r.version)).toList());}
 public List<Advance> advances(){return tx.execute(()->em.createQuery("select r from SupplierAdvance r order by r.id",SupplierAdvance.class).setMaxResults(500).getResultList().stream().map(r->new Advance(r.id,r.supplierId,""+r.originalXaf,""+r.allocatedXaf,""+Math.subtractExact(r.originalXaf,r.allocatedXaf),r.version)).toList());}
 public void applyPayment(UUID id,UUID supplier,long amount){tx.execute(()->{var s=TenantContext.current();var r=em.find(PayableBalance.class,new PayableBalance.Key(s.tenantId(),s.companyId(),id),LockModeType.PESSIMISTIC_WRITE);if(r==null)throw new NoSuchElementException("Scoped payable not found");if(!r.supplierId.equals(supplier)||amount<=0||amount>Math.subtractExact(r.originalXaf,r.paidXaf))throw new IllegalArgumentException("Supplier mismatch or payment exceeds payable");r.paidXaf=Math.addExact(r.paidXaf,amount);em.flush();return null;});}
 public void createAdvance(UUID id,UUID supplier,long amount){tx.execute(()->{suppliers.requireEligible(supplier);if(amount<=0)throw new IllegalArgumentException("Positive amount required");var s=TenantContext.current();var r=new SupplierAdvance();r.tenantId=s.tenantId();r.companyId=s.companyId();r.branchId=s.branchId();r.id=id;r.supplierId=supplier;r.originalXaf=amount;em.persist(r);em.flush();return null;});}
 public void allocateAdvance(UUID id,UUID invoice,long amount){tx.execute(()->{var s=TenantContext.current();var r=em.find(SupplierAdvance.class,new SupplierAdvance.Key(s.tenantId(),s.companyId(),id),LockModeType.PESSIMISTIC_WRITE);if(r==null)throw new NoSuchElementException("Scoped advance not found");if(amount<=0||amount>Math.subtractExact(r.originalXaf,r.allocatedXaf))throw new IllegalArgumentException("Allocation exceeds advance");applyPayment(invoice,r.supplierId,amount);r.allocatedXaf=Math.addExact(r.allocatedXaf,amount);em.flush();return null;});}
}